		void RunFunctionAndAssertOneRow(int period, object currentDebit, object currentCredit, object closingDebit, object closingCredit)
		{
			DataTable result = DataUtils.GetDataTableFromQuery(TestConnection, string.Format("SELECT * FROM TrialBalanceBudget({0}, '878D7ACA-FFC3-49FC-9710-969CA0C0F2AC') WHERE CHARINDEX(HasData, CASE WHEN 'N' = 'Y' THEN 'Y N' ELSE 'Y' END) > 0", period));
			AssertEquals("Row Count", 1, result.Rows.Count);
			AssertEquals("Current Debit", currentDebit, result.Rows[0]["CurrentDebit"]);
			AssertEquals("Current Credit", currentCredit, result.Rows[0]["CurrentCredit"]);
			AssertEquals("Closing Debit", closingDebit, result.Rows[0]["ClosingDebit"]);
			AssertEquals("Closing Credit", closingCredit, result.Rows[0]["ClosingCredit"]);
		}
	}
